// The transcription ladder (contracts §2.9) and the gym slot rule (§2.5). L1–L4 are generated by
// @oak/drills (`generateLadderPiece`), never authored by hand; L5, L6 and L8 draw on the repertoire pool
// (L5 and L6 items are cut from the songs' answer keys by content/gym/songs.ts).
import type { LadderLevelDef, SessionId, SongId } from "@oak/content-kit";
import { repertoire } from "../repertoire/index.ts";

const pool = (level: 5 | 6 | 8): SongId[] =>
  repertoire.filter((s) => s.ladder === level && !s.onlyWhenVerified).map((s) => s.id);

export const ladder: readonly LadderLevelDef[] = [
  {
    level: 1,
    title: "Drum loops",
    material: "generated-drums",
    grading: "auto",
    layers: ["drums"],
    generator: "ladder.drums",
    pass: 0.85,
  },
  {
    level: 2,
    title: "Bass lines",
    material: "generated-bass",
    grading: "auto",
    layers: ["bass"],
    generator: "ladder.bass",
    pass: 0.85,
  },
  {
    level: 3,
    title: "Four-chord loops, bass first",
    material: "generated-loop",
    grading: "auto",
    layers: ["bass", "chords"],
    generator: "ladder.loop",
    pass: 0.8,
  },
  {
    level: 4,
    title: "Short melodies",
    material: "generated-melody",
    grading: "auto",
    layers: ["melody"],
    generator: "ladder.melody",
    pass: 0.85,
  },
  {
    level: 5,
    title: "Public-domain folk",
    material: "pd-folk",
    grading: "auto",
    // The melody is graded, one phrase at a time; the chords and a root bass play as accompaniment
    // (content/gym/songs.ts, U11 spec "The ladder").
    layers: ["melody"],
    pool: pool(5),
    pass: 0.85,
  },
  {
    level: 6,
    title: "Blues and standards (≤ 1930)",
    material: "pd-standard",
    grading: "auto",
    layers: ["bass", "chords", "melody"],
    pool: pool(6),
    pass: 0.85,
  },
  {
    level: 7,
    title: "Your own audio",
    material: "own-audio",
    grading: "self",
    layers: ["melody", "bass", "chords", "form"],
    pass: 1,
  },
  {
    level: 8,
    title: "A full arrangement",
    material: "full-arrangement",
    grading: "auto",
    layers: ["form", "bass", "chords", "melody"],
    pool: pool(8),
    pass: 0.85,
  },
];

/** Where each level first becomes available (§2.9 table). */
export const LADDER_FIRST: Readonly<Record<number, (SessionId | "gym" | "even-gym")[]>> = {
  1: ["U01.L09", "GYM.01"],
  2: ["gym"],
  3: ["gym"],
  4: ["gym"],
  5: ["X1.S1", "gym"],
  6: ["X2.S1", "gym"],
  7: ["even-gym"],
  8: ["CF-T.S1"],
};

/** The slot rule of §2.5: from U07.L01, every 5th session is a transcription session. */
export const GYM_SLOT_RULE = {
  startsAt: "U07.L01" as SessionId,
  sessionsBetween: 4,
  /** Odd GYM numbers: graded ladder sessions; even: own-audio (or a ladder session one realism level up). */
  odd: "ladder",
  even: "own-audio",
  /** These count as transcription sessions and reset the counter. */
  resets: ["GYM", "X1", "X2", "CF-T"],
} as const;
